// Generated by `just generate` from `src/plugins/claudetto/slices/minispec/domain/tiers.ts`. Edit the source and run `just generate`.
// The size tiers of a change (spec `minispec`, "Size tiers").
// A small task has no change folder. A medium change has a proposal and tasks. A big or large change adds a design and specs.

/** The tiers that have a change folder. */
export const TIERS = ["medium", "big", "large"] as const;

export type Tier = (typeof TIERS)[number];

/** True when `value` is a tier that has a change folder. */
export const isTier = (value: string): value is Tier =>
  (TIERS as readonly string[]).includes(value);

/** True when the tier also has a design and specs. */
export const hasDesign = (tier: Tier): boolean => tier !== "medium";

/** The tier of an existing change, from its files: a design or a specs folder makes it big. */
export const tierOf = (files: {
  readonly design: boolean;
  readonly specs: boolean;
}): Tier => (files.design || files.specs ? "big" : "medium");
